def simulate_period(inputs_list, weights, capacity, start_day, end_day):
    # Initialize state
    stock = {}
    backordered = {}
    orders = [] # list of dicts: {pid, day, remaining}

    # Gather opening stocks
    for inp in inputs_list:
        if inp['kind'] == 'opening_stock':
            pid = inp['entities'][0]
            stock[pid] = inp['fields']['opening_stock']
            backordered[pid] = 0.0

    results = []

    # Group inputs by day
    day_inputs = {}
    for inp in inputs_list:
        if inp['time'] is not None and inp['kind'] in ('production', 'order'):
            d = inp['time']
            if d not in day_inputs: day_inputs[d] = {}
            if d not in day_inputs: day_inputs[d] = {}
            pid = inp['entities'][0]
            if pid not in day_inputs[d]: day_inputs[d][pid] = {'produced': 0, 'ordered': 0}
            if inp['kind'] == 'production':
                day_inputs[d][pid]['produced'] = inp['fields']['produced']
            elif inp['kind'] == 'order':
                day_inputs[d][pid]['ordered'] = inp['fields']['ordered']

    days = sorted([d for d in day_inputs.keys() if start_day <= d <= end_day])

    for day in days:
        day_shipped = {pid: 0 for pid in stock}

        # 1. Production arrives
        for pid, data in day_inputs[day].items():
            if data['produced'] > 0:
                stock[pid] += data['produced']

        # 2. Orders join queue
        for pid, data in day_inputs[day].items():
            if data['ordered'] > 0:
                orders.append({'pid': pid, 'day': day, 'remaining': data['ordered']})
                backordered[pid] += data['ordered']

        # 3. Dispatch
        # Sort orders: oldest first, then smaller remaining, then lower pid
        active_orders = [o for o in orders if o['remaining'] > 0]
        active_orders.sort(key=lambda o: (o['day'], o['remaining'], o['pid']))

        remaining_cap = capacity
        for order in active_orders:
            if remaining_cap <= 0: break
            pid = order['pid']
            weight = weights.get(pid, 0)
            if weight <= 0: continue # shouldn't happen

            max_by_stock = stock[pid]
            max_by_cap = remaining_cap // weight
            units = min(order['remaining'], max_by_stock, max_by_cap)

            if units > 0:
                day_shipped[pid] += units
                stock[pid] -= units
                remaining_cap -= units * weight
                order['remaining'] -= units
                backordered[pid] -= units

        # 4. Records
        for pid in stock:
            results.append({'time': day, 'kind': 'shipped', 'entities': [pid], 'value': day_shipped[pid]})
            results.append({'time': day, 'kind': 'backordered', 'entities': [pid], 'value': backordered[pid]})
            results.append({'time': day, 'kind': 'stock', 'entities': [pid], 'value': stock[pid]})

    return results

